function market(s) {
  return `<div class="panel"><div class="panel-label">FREE AGENT MARKET <span>IMMEDIATE IMPACT</span></div><p class="intro">Sign a two-year contract and replace your current player at that position. Full first-year salary is paid now; the departing player's salary is not refunded. Rivals sign players every three weeks. ${Game.rookieReserve(s) ? money(Game.rookieReserve(s)) + " is reserved for rookie contracts; " + money(Game.spendable(s)) + " is available to spend." : ""}</p>${s.market.map((p) => `<div class="player"><span class="position">${p.pos}</span><div class="player-name"><b>${p.name}</b><small>AGE ${p.age} · ${p.years}-YEAR CONTRACT · CEILING ${p.potential}</small></div><strong class="rating">${p.rating}</strong>${button("Sign · " + money(p.salary) + "/yr", "sign:" + p.id, !Game.canManage(s) || Game.spendable(s) < p.salary)}</div>`).join("") || "<p>The market is empty. A new class arrives next season.</p>"}</div>`;
}
